import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
S_FAIL = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
S_WEEK_FAIL = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
S_MENU = 'Sizi ana menüye yönlendiriyorum.'
ENV = dict(ani='', lang='tr')

def tr3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    p = []
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def tr_int(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            out.append('bin' if (val == 1000 and q == 1) else tr3(q) + ' ' + name)
    if n:
        out.append(tr3(n))
    return ' '.join(out)

def num(x):
    try:
        return float(str(x).strip())
    except Exception:
        return 0.0

def money(x, cur):
    c = int(round(abs(num(x)) * 100))
    w, f = divmod(c, 100)
    if cur == 'TL':
        if f and w:
            return tr_int(w) + ' lira ' + tr_int(f) + ' kuruş'
        if f:
            return tr_int(f) + ' kuruş'
        return tr_int(w) + ' Türk Lirası'
    unit = dict(USD='dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    sub = 'peni' if cur == 'GBP' else 'sent'
    if f and not w:
        return tr_int(f) + ' ' + sub
    s = tr_int(w) + ' ' + unit
    if f:
        s = s + ' ' + tr_int(f) + ' ' + sub
    return s

def cop(s):
    for end, suf in (('Türk Lirası', "'dır"), ('kuruş', 'tur'), ('dolar', 'dır'), ('sent', 'tir'), ('Euro', "'dur"), ('İngiliz Sterlini', "'dir"), ('peni', 'dir')):
        if s.endswith(end):
            return s + suf
    return s

def pdate(s):
    s = str(s or '').strip()
    m = re.match(r'^(\d{1,2})\.(\d{1,2})\.(\d{4})$', s)
    try:
        if m:
            return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
        m = re.match(r'^(\d{4})-(\d{2})-(\d{2})', s)
        if m:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None
    return None

def dtext(d):
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)

def ycop(y):
    o = y % 10
    t = (y // 10) % 10
    if o:
        return ["", "'dir", "'dir", "'tür", "'tür", "'tir", "'dır", "'dir", "'dir", "'dur"][o]
    if t:
        return ["", "'dur", "'dir", "'dur", "'tır", "'dir", "'tır", "'tir", "'dir", "'dır"][t]
    return "'dür" if (y // 100) % 10 else "'dir"

def today_of(v):
    return pdate(str(v.get('now') or '')[:10])

def digits_words(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())

def card_name(n):
    n = ' '.join(str(n or '').split())
    low = n.lower()
    if not n or len(n.split()) > 5 or len(n) > 40:
        return ''
    for w in ('talimat', 'yok say', 'numara', 'ignore', 'instruction', 'prompt'):
        if w in low:
            return ''
    return n

def is_main(c):
    return str(c.get('isMainCard')).strip().lower() != 'false'

def last4_of(c):
    l4 = re.sub(r'\D', '', str(c.get('cardNumberLast4') or ''))
    if len(l4) != 4:
        l4 = re.sub(r'\D', '', str(c.get('cardNumber') or ''))[-4:]
    return l4

def load_cards(v):
    cards = []
    raw = v.get('cards_json')
    try:
        if isinstance(raw, str) and raw.strip().startswith('['):
            cards = json.loads(raw)
        elif isinstance(raw, list):
            cards = raw
    except Exception:
        cards = []
    if not cards:
        tmp = dict()
        for k in list(v.keys()):
            m = re.search(r'\.cards\.(\d+)\.(cardNumber|cardNumberLast4|productName|status|isMainCard)$', str(k))
            if m:
                tmp.setdefault(int(m.group(1)), dict())[m.group(2)] = v.get(k)
        cards = [tmp[i] for i in sorted(tmp)]
    return [c for c in cards if isinstance(c, dict) and c.get('cardNumber')]

def envelope(result):
    body = result.get('data') if isinstance(result.get('data'), dict) else dict()
    bd = body.get('data') if isinstance(body.get('data'), dict) else dict()
    res = body.get('result') if isinstance(body.get('result'), dict) else dict()
    ok = str(result.get('status') or 'success').lower() == 'success' and str(res.get('returnCode') or '') == '1' and bool(bd)
    return body, bd, res, ok

def select_question(cards, idxs):
    names = []
    for i in idxs:
        n = card_name(cards[i - 1].get('productName'))
        if n and n.lower() not in [x.lower() for x in names]:
            names.append(n)
    if len(names) >= 2:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
    if len(names) == 1:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + names[0] + ' diyebilirsiniz.'
    return 'Hangi kartınızın borcunu öğrenmek istersiniz? Kartınızın son dört hanesini söyleyebilirsiniz.'

