                rules.append('  - Son altı haneler (yalnızca eşleştirmek için, ASLA söyleme): ' + '; '.join('sıra ' + str(i) + ' = ' + x for i, x in zip(same, l6)) + '. Eşleşen kartın borcunu oku; eşleşmezse tekrar sor.')
            else:
