def tr3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    p = []
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def tr_int(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            out.append('bin' if (val == 1000 and q == 1) else tr3(q) + ' ' + name)
    if n:
        out.append(tr3(n))
    return ' '.join(out)

def num(x):
    try:
        return float(str(x).strip())
    except Exception:
        return 0.0

def money(x, cur):
    c = int(round(abs(num(x)) * 100))
