        if not due:
            return ''
        if today and due == today:
            return 'Borçlarınız için son ödeme tarihiniz bugündür.'
        return 'Borçlarınız için son ödeme tarihiniz ' + dtext(due) + ycop(due.year) + '.'
    def totals(first_prefix):
        parts = []
        debts = [(code, label, b) for code, label, b in present if num(b.get('totalDebt')) > 0]
        for j, (code, label, b) in enumerate(debts):
            s = 'toplam ' + label + ' borcunuz ' + cop(money(b.get('totalDebt'), code)) + '.'
            parts.append((first_prefix + s) if j == 0 else ('Gelecek dönemler dahil ' + s))
        clear = [label for code, label, b in present if num(b.get('totalDebt')) <= 0]
        if not debts:
            parts.append(intro + 'a ait gelecek dönemler dahil borcunuz bulunmamaktadır.')
        elif clear:
            parts.append(nodebt(clear))
        return parts, bool(debts)
    parts = []
    has_debt = False
    branch = 'normal'
    if not st:
        branch = 'new'
        parts.append(intro + 'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
        if nst:
            parts.append('İlk hesap kesim tarihiniz ' + dtext(nst) + ' olacak.')
    elif today and (today == nst or today == st):
        branch = 'cutday'
        parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        p, has_debt = totals(intro + 'a ait gelecek dönemler dahil ')
        parts.extend(p)
        if due and today and due >= today:
            parts.append(due_sentence())
    else:
        debts = [(code, label, b) for code, label, b in present if num(b.get('remainingDebt')) > 0]
        if not debts:
            branch = 'nodebt'
            parts.append(intro + 'ın ' + dtext(st) + ' tarihli ekstresinden borcunuz bulunmamaktadır.')
            tl = bd.get('debtTL') if isinstance(bd.get('debtTL'), dict) else dict()
            if num(tl.get('totalDebt')) > 0:
                parts.append('Gelecek dönemler dahil toplam borcunuz ' + cop(money(tl.get('totalDebt'), 'TL')) + '.')
            if due and (not today or due > today):
                parts.append('Son ödeme tarihiniz ' + dtext(due) + ' olacaktır.')
            elif due and today and due == today:
                parts.append('Son ödeme tarihiniz bugündür.')
        elif today and due and today > due:
            branch = 'passed'
            parts.append(intro + 'ın ' + dtext(st) + ' tarihli ekstresinin son ödeme tarihi olan ' + dtext(due) + ' geçmiştir.')
            p, has_debt = totals('Gelecek dönemler dahil ')
            parts.extend(p)
            tl = bd.get('debtTL') if isinstance(bd.get('debtTL'), dict) else dict()
            if str(bd.get('automaticPaymentFlag') or '').upper() == 'Y' and num(tl.get('remainAutomaticPaymentAmount')) > 0:
                parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + cop(money(tl.get('remainAutomaticPaymentAmount'), 'TL')) + '.')
        else:
            has_debt = True
            sents = []
            moved = [label for code, label, b in present if code != 'TL' and num(b.get('transferAmount')) > 0]
            for code, label, b in debts:
                sd, mp, rd, rmp = b.get('statementDebt'), b.get('minPayment'), b.get('remainingDebt'), b.get('remainingMinPayment')
                if code == 'TL':
                    if moved:
                        sents.append(' ve '.join(moved) + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
                    if num(rmp) > 0 and num(rmp) >= num(mp):
                        sents.append('Türk Lirası borcunuz ' + money(sd, code) + ', ödenmesi gereken minimum tutar ' + cop(money(mp, code)) + '.')
                    elif num(rmp) <= 0:
                        sents.append('Türk Lirası borcunuz ' + money(sd, code) + ', kalan toplam borcunuz ' + cop(money(rd, code)) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
                    else:
                        sents.append('Türk Lirası borcunuz ' + money(sd, code) + ', ödenmesi gereken minimum tutar ' + money(mp, code) + ', kalan toplam borcunuz ' + money(rd, code) + ', kalan minimum ödeme tutarınız ' + cop(money(rmp, code)) + '.')
                else:
                    sents.append(label + ' borcunuz ' + money(sd, code) + ', kalan toplam borcunuz ' + money(rd, code) + ', ödenmesi gereken minimum tutar ' + cop(money(mp, code)) + '.')
            sents[0] = intro + 'a ait ' + dtext(st) + ' tarihinde kesilen ekstre ' + sents[0]
            parts.extend(sents)
            clear = [label for code, label, b in present if num(b.get('remainingDebt')) <= 0]
            nd = nodebt(clear)
            if nd:
                parts.append(nd)
            ds = due_sentence()
            if ds:
                parts.append(ds)
    text = ' '.join(x for x in parts if x)
    try:
        read = json.loads(str(v.get('read_cards') or '[]'))
    except Exception:
